```bash
cat <<'EOF' > test_gradients.py
import autograd.numpy as np
import autograd.numpy.random as npr
from autograd import grad

# Test gradient computations
x = npr.randn(4, 4)

def simple_function(x):
    return np.sum(np.abs(np.fft.fft(x))**2)

try:
    grad_fn = grad(simple_function)
    result = grad_fn(x)
    print("fft gradient: Success")
except Exception as e:
    print(f"fft gradient: Error - {type(e).__name__}: {e}")

def simple_function2(x):
    return np.sum(np.abs(np.fft.fftn(x))**2)

try:
    grad_fn = grad(simple_function2)
    result = grad_fn(x)
    print("fftn gradient: Success")
except Exception as e:
    print(f"fftn gradient: Error - {type(e).__name__}: {e}")
EOF
